'use strict';
const PEOPLE_UI6={peopleView,managementView,bind,help};
function personStoryHtml6(s){const p=characterProfile6(s.pid).person;return `<article class="card"><span class="eyelabel">OSOBNÍ ZPRÁVA · DO T${s.due}</span><h3>${esc(s.name)} · ${esc(s.title)}</h3><p class="sub">${esc(CHARACTER_TYPES6[p.character6.trait].motivation)}. ${s.type==='care'?'Podpora poskytne dva týdny placeného volna. Smluvní mzda pokračuje; směny musí pokrýt kolegové. Za tři týdny se ověří skutečné přetížení.':'Podpora zaplatí školení '+CREW_SKILLS5[s.skill]+' +6. Za tři týdny se ověří dosažená dovednost.'}</p><div class="actions">${[['support','Podpořit žádost'],['bonus','Bonus 5 000 Kč'],['decline','Odmítnout']].map(([choice,label])=>`<button class="${choice==='support'?'primary':'soft'}" data-person-answer6="${s.id}" data-person-choice6="${choice}">${label}</button>`).join('')}<button class="quiet" data-person-profile6="${s.pid}">Profil a příběh</button></div></article>`;}
function peopleStoriesHtml6(){return `<section class="card" style="margin-top:24px"><h2>Osobní zprávy z týmů</h2>${state.people6.stories.map(personStoryHtml6).join('')||empty('Nové žádosti vycházejí z přetížení a rozvojových cílů konkrétních lidí.')}<h3>Lidé mají vlastní povahu a paměť</h3><div class="actions">${peopleOwned6().slice(0,24).map(a=>`<button class="soft mini" data-person-profile6="${a.person.pid}">${esc(a.person.name)} · ${esc(CHARACTER_TYPES6[a.person.character6.trait].name)}</button>`).join('')||empty('Najmi první tým.')}<button class="soft" id="personDirectory6">Všichni lidé a kandidáti</button></div></section>`;}
peopleView=function(){return PEOPLE_UI6.peopleView()+peopleStoriesHtml6();};
function personProfileDialog6(pid){const x=characterProfile6(pid),p=x.person,c=p.character6,t=CHARACTER_TYPES6[c.trait],owner=peopleOwned6().find(x=>x.person.pid===pid);show(`<span class="eyelabel">OSOBNOST A NAVAZUJÍCÍ PŘÍBĚH</span><h2>${esc(p.name)}</h2><p>${esc(t.bio)}</p>${rows([['Povaha',t.name],['Co člověk hledá',t.motivation],['Vztah s firmou',number(c.relationship,1)+'/100'],['Působiště',owner?(loc(owner.target)?.name||owner.target):'Kandidát nebo jiné působiště'],['Osobní manažerská strategie',x.kind==='manager'?MANAGER_STRATEGIES6[t.strategy].name:'Rozvoj do další role']])}${x.kind==='manager'?`<p class="sub">${esc(MANAGER_STRATEGIES6[t.strategy].description)} Strategie se použije v chytrém řízení pouze při povolení osobní strategie; ruční cíle a pravomoci máš ve správě vedení.</p>`:''}${c.commitment?`<div class="warning">Navazující dohoda do T${c.commitment.due}: ${c.commitment.type==='care'?'přetížení':CREW_SKILLS5[c.commitment.skill]} · cíl ${number(c.commitment.target,1)}. Výsledek bude z reálné evidence.</div>`:''}<h3>Co se stalo a co firma slíbila</h3>${c.memory.length?c.memory.slice().reverse().map(m=>`<div class="news"><strong>T${m.week}</strong><span>${esc(m.text)}</span></div>`).join(''):empty('Zatím bez společného příběhu.')}<div class="actions"><button class="soft" id="personDirectoryBack6">Přehled lidí</button><button class="soft" data-goto="management">Strategie a pravomoci</button></div>`);el('personDirectoryBack6').onclick=personDirectory6;on('[data-goto]',b=>{el('modal').close();goto(b.dataset.goto)});}
function personDirectory6(){show(`<h2>Lidé a kandidáti</h2><p class="sub">Profil zachovává identitu, povahu, vztah a paměť i při přestupu.</p><div class="fields">${field('Hledat jméno','<input id="personSearch6" type="search" placeholder="Jméno člověka">')}${field('Role',`<select id="personRole6"><option value="all">Všichni</option><option value="manager">Vedoucí</option><option value="barista">Baristé</option></select>`)}</div><div id="personDirectoryRows6"></div>`);const refresh=()=>{const query=el('personSearch6').value.toLocaleLowerCase('cs'),role=el('personRole6').value,list=peopleAll6().filter(a=>(role==='all'||a.kind===role)&&a.person.name.toLocaleLowerCase('cs').includes(query));el('personDirectoryRows6').innerHTML=list.map(a=>`<div class="vote"><div><strong>${esc(a.person.name)}</strong><small>${esc(CHARACTER_TYPES6[a.person.character6.trait].name)} · ${a.kind==='manager'?'vedoucí':'barista'}</small></div><button class="soft mini" data-person-profile6="${a.person.pid}">Profil</button></div>`).join('')||empty('Nikdo neodpovídá filtru.');on('[data-person-profile6]',b=>personProfileDialog6(b.dataset.personProfile6));};el('personSearch6').oninput=el('personRole6').onchange=refresh;refresh();}
function personReplyDialog6(id,choice){const q=peopleStoryQuote6(id,choice),s=state.people6.stories.find(s=>s.id===id);show(`<h2>${esc(s.name)} · ${esc(s.title)}</h2>${rows([['Odpověď',({support:'Podpora',bonus:'Bonus',decline:'Odmítnutí'})[choice]],['Platba',money(q.fee)],['Zbývající hotovost',money(q.cash-q.fee)]])}<p class="sub">${choice==='support'?(s.type==='care'?'Dva týdny placeného volna. Zkontroluj pokrytí směn.':'Školení zvolené dovednosti +6; nejvýše jedno školení osoby za týden.'):'Volba zůstane v příběhu člověka.'}</p><div class="actions"><button class="primary" id="personReplyConfirm6" ${state.over||q.cash<q.fee?'disabled':''}>Potvrdit odpověď</button><button class="soft" id="personReplyCancel6">Zrušit</button></div>`);el('personReplyCancel6').onclick=()=>el('modal').close();el('personReplyConfirm6').onclick=()=>act(()=>{resolvePeopleStory6(id,choice,q);el('modal').close();render()});}
managementView=function(){const html=PEOPLE_UI6.managementView(),s=state.stores.find(s=>s.id===managementStore5);if(!s)return html;const p=s.management5,owner=owner5(s)?.person,strategy=owner?CHARACTER_TYPES6[owner.character6.trait].strategy:'saver',extra=`<label class="checkbox-line"><input type="checkbox" id="smartPersonal6" ${p.personal6?'checked':''}> Použít osobní strategii odpovědného vedoucího: ${esc(MANAGER_STRATEGIES6[strategy].name)}</label>${field('Samostatný limit školení / týden',input('smartInvestment6',p.investment6,0,50000,1000))}<p class="sub">Osobní strategie vybírá jen z povolených variant. Školení potřebuje vlastní limit a rezervu; nepřepíše ruční rozpis. Při vypnutí platí hlavní cíl zvolený níže. Ziskové odhady zahrnují DPH, odvody, přesčasy a odpisy. Jídlo a balení drží poslední známý příspěvek; skutečný výsledek se může změnit zásobami, odpadem nebo dalšími zásahy.</p>`;return html.replace('<button class="primary" id="smartSave5">',extra+'<button class="primary" id="smartSave5">')+`<section class="card" style="margin-top:24px"><h2>Osobní strategie · dosažený výsledek</h2>${state.management5.decisions.filter(r=>r.strategy6).slice(-10).reverse().map(r=>`<div class="news"><div><strong>T${r.week} · ${esc(r.author)} · ${esc(MANAGER_STRATEGIES6[r.strategy6].name)}</strong><p>${esc(r.action)}</p><p class="sub">${r.evaluation6?esc(r.evaluation6.text)+' Rozdíl skutečnosti vůči odhadu '+money(r.evaluation6.deltaObserved)+'.':'Čeká na konečný výsledek týdne.'}</p></div></div>`).join('')||empty('Zapni osobní strategii a odehraj týden.')}<p class="sub">Srovnání odhadu se skutečností neprokazuje příčinný přínos jediného zásahu.</p></section>`;};
bind=function(){PEOPLE_UI6.bind();on('[data-person-profile6]',b=>personProfileDialog6(b.dataset.personProfile6));on('[data-person-answer6]',b=>{try{personReplyDialog6(b.dataset.personAnswer6,b.dataset.personChoice6)}catch(e){toast(e.message)}});if(el('personDirectory6'))el('personDirectory6').onclick=personDirectory6;if(el('smartSave5'))el('smartSave5').onclick=()=>act(()=>{setSmartManager5(managementStore5,{enabled:el('smartEnabled5').checked,budget:Number(el('smartBudget5').value),reserve:Number(el('smartReserve5').value),goal:el('smartGoal5').value,personal6:el('smartPersonal6').checked,investment6:Number(el('smartInvestment6').value)});toast('Řízení a osobní strategie uloženy.');render()});};
help=function(){PEOPLE_UI6.help();const p=document.createElement('p');p.textContent='Lidé mají profil, povahu, rozvojové cíle a vlastní paměť. Osobní žádosti z týmu se objeví v týdenním přehledu; podpora skutečně zaplatí školení nebo dočasně uvolní směny. Navazující dohoda se vyhodnotí podle dosažené dovednosti nebo přetížení. V řídicím přehledu lze povolit osobní strategii odpovědného vedoucího; její provedené kroky porovnají odhad se skutečným výsledkem.';el('modalContent').append(p);};el('help').onclick=help;render();
